import { db } from "@/lib/db";
import { getSetting, SETTINGS_DEFAULTS } from "@/lib/settings";
import { brandLabel } from "@/lib/stripe-cards";
import { appOrigin } from "@/lib/public-origin";
import type { Invoice, InvoiceStatus, Prisma, User } from "@prisma/client";

/**
 * Seller identity + number prefix printed on an invoice, resolved from Settings →
 * General/Billing. Read once per render and handed to the (synchronous) renderer.
 */
export type InvoiceBranding = {
  /** `invoice_prefix`, never blank — see `invoiceBranding()`. */
  numberPrefix: string;
  /** `brand_name`, never blank. */
  brandName: string;
  /** `company_legal_name` — "" means "omit the seller block". */
  legalName: string;
  /** `company_address` — "" means "omit the seller address". */
  address: string;
};

const FALLBACK_BRANDING: InvoiceBranding = {
  numberPrefix: SETTINGS_DEFAULTS.invoice_prefix,
  brandName: SETTINGS_DEFAULTS.brand_name,
  legalName: "",
  address: "",
};

/**
 * Read the invoice branding from Settings.
 *
 * `numberPrefix` is forced non-empty. `Invoice.number` is a bare autoincrement, so an
 * operator who clears the field would otherwise produce documents identified only as
 * "00012" — not quotable to a customer, not greppable in a mailbox, and impossible to
 * tell apart from a server ID or an order number in a support thread.
 *
 * `legalName`/`address` stay blank-able by design: the seller block is omitted entirely
 * when they are unset, rather than printing an empty "From" heading. That is why the
 * "shown on invoices" claim on the admin field is now true without the panel having to
 * demand a value it does not have.
 */
export async function invoiceBranding(): Promise<InvoiceBranding> {
  const [prefix, brandName, legalName, address] = await Promise.all([
    getSetting("invoice_prefix"),
    getSetting("brand_name"),
    getSetting("company_legal_name"),
    getSetting("company_address"),
  ]);
  return {
    numberPrefix: prefix.trim() || SETTINGS_DEFAULTS.invoice_prefix,
    brandName: brandName.trim() || SETTINGS_DEFAULTS.brand_name,
    legalName: legalName.trim(),
    address: address.trim(),
  };
}

/**
 * The customer-facing invoice identifier: the configured prefix plus the zero-padded
 * autoincrement (`INV-00012`).
 *
 * One function so every surface agrees. The padding was previously duplicated as
 * `#${String(n).padStart(5, "0")}` at eight call sites, which is precisely why
 * `invoice_prefix` had no reader — there was no single place to wire it. The `#` sigil
 * is dropped now that a prefix is always present; keeping both would render `#INV-00012`.
 */
export function formatInvoiceNumber(
  number: number,
  prefix: string = SETTINGS_DEFAULTS.invoice_prefix,
): string {
  return `${prefix}${String(number).padStart(5, "0")}`;
}

/**
 * Invoice line item shape stored in `Invoice.lineItems` (Json).
 * Amounts are integer cents. `amountCents` is authoritative; qty * unitCents
 * is used as a fallback when a line omits it.
 */
export type LineItem = {
  description: string;
  qty: number;
  unitCents: number;
  amountCents: number;
};

export function coerceLineItems(raw: unknown): LineItem[] {
  if (!Array.isArray(raw)) return [];
  return raw
    .filter((x): x is Record<string, unknown> => !!x && typeof x === "object")
    .map((x) => {
      const qty = Number(x.qty ?? 1) || 0;
      const unitCents = Math.round(Number(x.unitCents ?? 0) || 0);
      const amountCents = Math.round(
        Number(x.amountCents ?? qty * unitCents) || 0
      );
      return {
        description: String(x.description ?? "Item"),
        qty,
        unitCents,
        amountCents,
      };
    });
}

/** Compute subtotal / tax / total (all integer cents) for an invoice. */
export function invoiceTotals(invoice: Pick<Invoice, "lineItems" | "taxCents" | "amountCents">) {
  const items = coerceLineItems(invoice.lineItems);
  const subtotalCents = items.reduce((sum, li) => sum + li.amountCents, 0);
  const taxCents = invoice.taxCents ?? 0;
  // `amountCents` is the stored authoritative total; fall back to computed.
  const totalCents = invoice.amountCents ?? subtotalCents + taxCents;
  return { items, subtotalCents, taxCents, totalCents };
}

const STATUS_LABEL: Record<InvoiceStatus, string> = {
  OPEN: "Open",
  PAID: "Paid",
  VOID: "Void",
  REFUNDED: "Refunded",
};

export function invoiceStatusLabel(status: InvoiceStatus): string {
  return STATUS_LABEL[status] ?? status;
}

/**
 * Human-readable payment method / status line for an invoice.
 *
 * PAID/REFUNDED → "Paid with Visa •••• 4242 on Aug 3, 2026", using the stamped
 * card snapshot (`paidBrand`/`paidLast4`). For invoices issued before the snapshot
 * existed those are null, so we FALL BACK to the user's current card fields —
 * historical invoices still read correctly. If no card is known at all we show a
 * plain "Paid …". OPEN → "Awaiting payment"; VOID → "Void".
 */
export function invoicePaymentMethod(
  invoice: Pick<Invoice, "status" | "paidAt" | "paidBrand" | "paidLast4">,
  fallbackCard?: { cardBrand: string | null; cardLast4: string | null } | null,
): string {
  if (invoice.status === "OPEN") return "Awaiting payment";
  if (invoice.status === "VOID") return "Void";

  const brand = invoice.paidBrand ?? fallbackCard?.cardBrand ?? null;
  const last4 = invoice.paidLast4 ?? fallbackCard?.cardLast4 ?? null;
  const verb = invoice.status === "REFUNDED" ? "Refunded" : "Paid";
  const when = invoice.paidAt ? ` on ${fmtDate(invoice.paidAt)}` : "";
  if (last4) return `${verb} with ${brandLabel(brand)} •••• ${last4}${when}`;
  return `${verb}${when}`;
}

export type InvoiceInput = {
  userId: string;

  userId: string;
  description: string;
  lineItems: LineItem[];
  taxCents?: number;
  /** VAT/GST rate (percent) applied to the net — recorded on the invoice (Finding 1). */
  taxRatePercent?: number;
  /** Destination country the tax was charged for (ISO-3166 alpha-2). */
  taxCountry?: string | null;
  status?: InvoiceStatus;
  period?: { start?: Date | null; end?: Date | null };
  /**
   * Card snapshot to stamp when this invoice is created already PAID (renewals,
   * auto-charges). Ignored for non-PAID invoices. Null-safe: a user with no saved
   * card leaves these null and the UI falls back to their current card fields.
   */
  paidBrand?: string | null;
  paidLast4?: string | null;
  /**
   * How much of this invoice's net (pre-tax) amount is a dedicated-IP surcharge
   * (2026-09-26, Creator Partner Program). OPTIONAL, defaults to 0 — every
   * existing caller that never bought/renewed a dedicated IP, or was written
   * before this field existed, is unaffected. Populated from the SAME `ipCents`
   * a charge path already computed (lib/order.ts, lib/game-order.ts,
   * worker/billing.ts), never re-derived from line items, so
   * lib/partner-commission.ts's dedicated-IP commission exclusion has a real,
   * typed number to read.
   */
  dedicatedIpCents?: number;
};

/**
 * Build the `data` payload for an Invoice row WITHOUT touching the database, so
 * a charge site can create the invoice inside its own guarded `$transaction`
 * (sharing the charge's idempotency guard) via `tx.invoice.create({ data })`.
 * The stored total (`amountCents`) is always derived from line items + tax so
 * callers can't desync the stamped total from the itemised breakdown.
 */
export function invoiceCreateData(opts: InvoiceInput): Prisma.InvoiceUncheckedCreateInput {
  const items = opts.lineItems.map((li) => ({
    description: String(li.description),
    qty: Number(li.qty) || 0,
    unitCents: Math.round(Number(li.unitCents) || 0),
    amountCents: Math.round(
      Number(li.amountCents ?? (Number(li.qty) || 0) * (Number(li.unitCents) || 0)) || 0
    ),
  }));
  const taxCents = Math.round(opts.taxCents ?? 0);
  const subtotalCents = items.reduce((s, li) => s + li.amountCents, 0);
  const amountCents = subtotalCents + taxCents;
  const status = opts.status ?? "OPEN";

  return {
    userId: opts.userId,
    description: opts.description,
    lineItems: items,
    taxCents,
    // Record the rate + jurisdiction on any invoice that actually collected tax; a
    // zero-tax invoice (top-up, unknown country, reverse charge) leaves them 0/null.
    taxRatePercent: taxCents > 0 ? Math.round((opts.taxRatePercent ?? 0) * 1e4) / 1e4 : 0,
    taxCountry: taxCents > 0 ? opts.taxCountry ?? null : null,
    dedicatedIpCents: Math.max(0, Math.round(opts.dedicatedIpCents ?? 0)),
    amountCents,
    status,
    paidAt: status === "PAID" ? new Date() : null,
    // Only stamp the paying card on invoices born PAID; an OPEN invoice has not
    // been charged to any card yet.
    paidBrand: status === "PAID" ? opts.paidBrand ?? null : null,
    paidLast4: status === "PAID" ? opts.paidLast4 ?? null : null,
    periodStart: opts.period?.start ?? null,
    periodEnd: opts.period?.end ?? null,
  };
}

/**
 * Create an Invoice row directly. The total (`amountCents`) is derived from the
 * line items plus tax so callers can't accidentally desync the stamped total
 * from the itemised breakdown.
 */
export async function createInvoice(opts: InvoiceInput): Promise<Invoice> {
  return db.invoice.create({ data: invoiceCreateData(opts) });
}

/** Caps for a multi-line line-item description (keeps a pasted wall of text from wrecking the layout). */
export const MAX_DESC_LINES = 12;
export const MAX_DESC_CHARS = 600;

/**
 * Split a line-item description into display lines: the first is the headline, the rest are
 * detail/spec sub-lines. Normalises CRLF, trims, drops blank lines, and caps the total at
 * `MAX_DESC_CHARS` characters / `MAX_DESC_LINES` lines (an over-long tail ends in "…").
 * A single-line description always comes back as exactly `[description]` (untouched apart from
 * the cap), so existing invoices render as before. Never throws; always returns >= 1 entry.
 */
export function invoiceDescriptionLines(desc: unknown): string[] {
  const raw = String(desc ?? "");
  const clipped = raw.length > MAX_DESC_CHARS ? raw.slice(0, MAX_DESC_CHARS - 1) + "…" : raw;
  const lines = clipped
    .split(/\r?\n|\r/)
    .map((l) => l.trim())
    .filter((l) => l.length > 0);
  if (lines.length === 0) return [raw.trim() ? raw.trim() : ""];
  if (lines.length > MAX_DESC_LINES) {
    const kept = lines.slice(0, MAX_DESC_LINES);
    kept[MAX_DESC_LINES - 1] = kept[MAX_DESC_LINES - 1].replace(/…?$/, "…");
    return kept;
  }
  return lines;
}

/** Brand navy of the invoice header band (--navy-900 in app/globals.css). */
export const INVOICE_HEADER_NAVY = "#0a101f";

/**
 * White-label rule: the real Nxeon logo is only shown when the configured brand name is the
 * platform default ("Nxeon"). Any other brand name gets its own name as text on the band, so the
 * invoice never presents Nxeon's logo as someone else's brand.
 */
export function invoiceUsesNxeonLogo(brandName: string): boolean {
  return brandName.trim().toLowerCase() === SETTINGS_DEFAULTS.brand_name.trim().toLowerCase();
}

function esc(s: unknown): string {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function money(cents: number): string {
  const neg = cents < 0;
  return `${neg ? "−" : ""}$${(Math.abs(cents) / 100).toFixed(2)}`;
}

function fmtDate(d: Date | null | undefined): string {
  if (!d) return "—";
  return new Date(d).toLocaleDateString("en-US", {
    year: "numeric",
    month: "short",
    day: "numeric",
  });
}

const STATUS_STAMP: Record<InvoiceStatus, { color: string; label: string }> = {
  PAID: { color: "#10b981", label: "PAID" },
  OPEN: { color: "#f59e0b", label: "OPEN" },
  VOID: { color: "#64748b", label: "VOID" },
  REFUNDED: { color: "#8a70fb", label: "REFUNDED" },
};

/**
 * Render a clean, print-ready branded HTML invoice. Intended to be served
 * standalone (users Print → Save as PDF — see the download route).
 *
 * `branding` is optional and defaults to the built-in values so this stays synchronous
 * and every existing caller keeps compiling. Async callers should pass
 * `await invoiceBranding()`; a caller that does not will render the platform defaults
 * (`INV-`, "Nxeon", no seller block) — identical to the pre-wiring output, never a blank.
 */
export function renderInvoiceHTML(
  invoice: Invoice,
  user: Pick<User, "name" | "email">,
  branding: InvoiceBranding = FALLBACK_BRANDING,
): string {
  const { items, subtotalCents, taxCents, totalCents } = invoiceTotals(invoice);
  const base = STATUS_STAMP[invoice.status] ?? STATUS_STAMP.OPEN;
  // VOID's slate is too dim on the navy header band; lift it (the stamp now sits on dark).
  const stamp = invoice.status === "VOID" ? { ...base, color: "#94a3b8" } : base;
  const number = formatInvoiceNumber(invoice.number, branding.numberPrefix);
  const period =
    invoice.periodStart || invoice.periodEnd
      ? `${fmtDate(invoice.periodStart)} – ${fmtDate(invoice.periodEnd)}`
      : null;

  const rows = items
    .map((li) => {
      const [head, ...details] = invoiceDescriptionLines(li.description);
      const subs = details.map((d) => `<div class="dsub">${esc(d)}</div>`).join("");
      return `
      <tr>
        <td class="desc">${esc(head)}${subs}</td>
        <td class="num">${esc(li.qty)}</td>
        <td class="num">${money(li.unitCents)}</td>
        <td class="num">${money(li.amountCents)}</td>
      </tr>`;
    })
    .join("");

  // Real logo (white wordmark, built for dark backgrounds) on the navy header band. Absolute URL
  // so the invoice still works when saved or emailed. White-label brands get their name as text.
  const logo = invoiceUsesNxeonLogo(branding.brandName)
    ? `<img class="logo" src="${esc(appOrigin())}/logo.png" alt="Nxeon" width="146" height="25"/>`
    : `<div class="name">${esc(branding.brandName)}</div>`;

  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1"/>
<title>${esc(branding.brandName)} Invoice ${esc(number)}</title>
<style>
  :root { color-scheme: light; }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    background: #f1f5f9;
    color: #0f172a;
    font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    font-size: 14px;
    line-height: 1.5;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }
  .sheet {
    max-width: 760px;
    margin: 32px auto;
    background: #fff;
    border-radius: 16px;
    box-shadow: 0 10px 40px rgba(15, 23, 42, 0.08);
    overflow: hidden;
  }
  .bar {
    height: 6px;
    background: linear-gradient(90deg, #3b82f6, #6f47f5);
  }
  .inner { padding: 4px 40px 40px; }
  .hdr { background: ${INVOICE_HEADER_NAVY}; color: #fff; padding: 30px 40px; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  .top { display: flex; justify-content: space-between; align-items: flex-start; gap: 24px; }
  .brand .logo { display: block; width: 146px; height: auto; max-width: 100%; }
  .brand .name { font-size: 22px; font-weight: 800; letter-spacing: -0.02em; color: #fff; }
  .brand .tag { font-size: 12px; color: #94a3b8; margin-top: 8px; }
  .meta { text-align: right; }
  .meta .no { font-size: 13px; color: #94a3b8; }
  .meta .num { font-size: 22px; font-weight: 800; letter-spacing: -0.02em; color: #fff; }
  .stamp {
    display: inline-block;
    margin-top: 8px;
    padding: 4px 12px;
    background: rgba(255, 255, 255, 0.06);
    border: 2px solid ${stamp.color};
    color: ${stamp.color};
    border-radius: 8px;
    font-weight: 800;
    font-size: 13px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }
  .parties { display: flex; gap: 40px; margin-top: 32px; flex-wrap: wrap; }
  .party { min-width: 200px; }
  .label { font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em; color: #94a3b8; font-weight: 700; margin-bottom: 6px; }
  .party .val { font-weight: 600; }
  .party .sub { color: #64748b; font-size: 13px; }
  table { width: 100%; border-collapse: collapse; margin-top: 32px; }
  thead th {
    text-align: left;
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: #94a3b8;
    font-weight: 700;
    padding: 0 0 10px;
    border-bottom: 1px solid #e2e8f0;
  }
  thead th.num, td.num { text-align: right; }
  tbody td { padding: 12px 0; border-bottom: 1px solid #f1f5f9; vertical-align: top; }
  td.desc { font-weight: 500; }
  td.desc .dsub { font-weight: 400; font-size: 12px; line-height: 1.5; color: #64748b; margin-top: 2px; }
  td.num { font-variant-numeric: tabular-nums; white-space: nowrap; }
  .totals { margin-top: 20px; display: flex; justify-content: flex-end; }
  .totals table { width: 280px; margin: 0; }
  .totals td { border: none; padding: 6px 0; }
  .totals .k { color: #64748b; }
  .totals .v { text-align: right; font-variant-numeric: tabular-nums; }
  .totals .grand td { border-top: 2px solid #0f172a; padding-top: 12px; font-size: 18px; font-weight: 800; }
  .foot { margin-top: 40px; padding-top: 20px; border-top: 1px solid #e2e8f0; color: #94a3b8; font-size: 12px; display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
  .print-btn {
    position: fixed; top: 20px; right: 20px;
    background: linear-gradient(90deg, #3b82f6, #6f47f5);
    color: #fff; border: none; border-radius: 10px;
    padding: 10px 18px; font-size: 13px; font-weight: 600; cursor: pointer;
    box-shadow: 0 6px 20px rgba(111, 71, 245, 0.35);
  }
  @media print {
    body { background: #fff; }
    .sheet { box-shadow: none; margin: 0; max-width: none; border-radius: 0; }
    .print-btn { display: none; }
  }
</style>
</head>
<body>
  <button class="print-btn" onclick="window.print()">Print / Save as PDF</button>
  <div class="sheet">
    <div class="bar"></div>
    <div class="hdr">
      <div class="top">
        <div class="brand">
          ${logo}
          <div class="tag">Cloud VPS Hosting</div>
        </div>
        <div class="meta">
          <div class="no">Invoice</div>
          <div class="num">${esc(number)}</div>
          <div class="stamp">${stamp.label}</div>
        </div>
      </div>
    </div>
    <div class="inner">

      <div class="parties">
        ${
          /*
           * Seller block ("From"). The admin field for `company_address` used to be
           * labelled "shown on invoices" while this document had no seller party at all,
           * so an operator with a VAT/GST obligation could enter their registered address,
           * see "Saved.", and still issue invoices with no seller on them.
           *
           * Rendered ONLY when at least one of the two keys is set: an empty "From"
           * heading above a blank line reads as a rendering bug on a financial document,
           * and is worse than the honest omission that shipped before.
           */
          branding.legalName || branding.address
            ? `<div class="party">
          <div class="label">From</div>
          ${branding.legalName ? `<div class="val">${esc(branding.legalName)}</div>` : ""}
          ${
            branding.address
              ? `<div class="sub">${esc(branding.address).replace(/\r?\n/g, "<br/>")}</div>`
              : ""
          }
        </div>`
            : ""
        }
        <div class="party">
          <div class="label">Billed to</div>
          <div class="val">${esc(user.name)}</div>
          <div class="sub">${esc(user.email)}</div>
        </div>
        <div class="party">
          <div class="label">Issued</div>
          <div class="val">${fmtDate(invoice.createdAt)}</div>
          ${invoice.paidAt ? `<div class="sub">Paid ${fmtDate(invoice.paidAt)}</div>` : ""}
          ${
            invoice.paidLast4
              ? `<div class="sub">${esc(brandLabel(invoice.paidBrand))} ···· ${esc(invoice.paidLast4)}</div>`
              : ""
          }
        </div>
        ${
          period
            ? `<div class="party"><div class="label">Service period</div><div class="val">${esc(period)}</div></div>`
            : ""
        }
      </div>

      <table>
        <thead>
          <tr>
            <th>Description</th>
            <th class="num">Qty</th>
            <th class="num">Unit</th>
            <th class="num">Amount</th>
          </tr>
        </thead>
        <tbody>
          ${rows || `<tr><td class="desc" colspan="4">${esc(invoice.description)}</td></tr>`}
        </tbody>
      </table>

      <div class="totals">
        <table>
          <tr><td class="k">Subtotal</td><td class="v">${money(subtotalCents)}</td></tr>
          <tr><td class="k">${
            taxCents > 0 && invoice.taxRatePercent
              ? `VAT / Tax (${invoice.taxRatePercent}%${invoice.taxCountry ? ` · ${esc(invoice.taxCountry)}` : ""})`
              : "Tax"
          }</td><td class="v">${money(taxCents)}</td></tr>
          <tr class="grand"><td>Total</td><td class="v">${money(totalCents)}</td></tr>
        </table>
      </div>

      <div class="foot">
        <div>${esc(invoice.description)}</div>
        <div>${esc(branding.brandName)} · Thank you for your business</div>
      </div>
    </div>
  </div>
</body>
</html>`;
}
