 *   - a balanced 6-round Feistel network over two 15-bit halves, round function =
 *     HMAC-SHA256(key, round || half) truncated to 15 bits. A Feistel network is a
 *     bijection no matter what the round function is, so codes are COLLISION-FREE by
 *     construction and the inverse (for support lookup) is the same rounds run backwards.
 *   - the 30-bit result is rendered as 6 chars of an unambiguous base-32 alphabet (no
 *     I, L, O, U — nothing a customer can misread over the phone).
 *   - without the key the mapping is not invertible and consecutive numbers map to
 *     unrelated codes, so neither ordering nor count can be read off a code.
 *
 * CEILING. Domain = 2^30 = 1,073,741,824. `Invoice.number` must be < 2^30; beyond that
 * `displayInvoiceNumber` falls back to the legacy form (and logs) rather than collide.
 * At 1,000,000 invoices/year that is >1,000 years.
 *
 * CUTOVER. Invoices that existed at deploy time keep their legacy display (customers
 * already hold those numbers). Only `number > INVOICE_OPAQUE_AFTER` use the new code.
 *
 * ENV (never in the DB, never logged):
 *   INVOICE_DISPLAY_KEY     secret, >= 16 chars. Treat like AUTH_SECRET: ROTATING IT
 *                           CHANGES EVERY NEW-STYLE CODE ALREADY ISSUED. Set once, back it up.
 *   INVOICE_OPAQUE_AFTER    integer cutoff = highest invoice number at deploy time.
 *
 * FAIL SAFE. Cutoff unset => feature off (legacy for everyone, silent: that is the
 * pre-deploy state). Cutoff set but key missing/short => legacy display + a loud
 * console.error (once per process), never a crash and never a code derived from a
 * default key.
 *
 * This is pure/synchronous (node:crypto only) so every renderer, including the PDF
 * and email paths, can call it.
 */

export const INVOICE_CODE_BITS = 30;
export const INVOICE_CODE_DOMAIN = 2 ** INVOICE_CODE_BITS;
export const INVOICE_CODE_LENGTH = 6;
const ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"; // Crockford base32
const ROUNDS = 6;
const MIN_KEY_LEN = 16;

export type OpaqueConfig = { key: string | null; after: number | null };

export function opaqueConfigFromEnv(env: NodeJS.ProcessEnv = process.env): OpaqueConfig {
  const rawAfter = (env.INVOICE_OPAQUE_AFTER ?? "").trim();
  const after = /^\d+$/.test(rawAfter) ? Number(rawAfter) : null;
  const k = env.INVOICE_DISPLAY_KEY ?? "";
  return { key: k.length >= MIN_KEY_LEN ? k : null, after };
}

/** Feistel half-width. */
const HALF_BITS = INVOICE_CODE_BITS / 2;
const HALF_MASK = (1 << HALF_BITS) - 1;

function roundFn(key: string, round: number, half: number): number {
  const mac = createHmac("sha256", key).update(`inv-code-v1|${round}|${half}`).digest();
  return ((mac[0] << 8) | mac[1]) & HALF_MASK;
}

/** Keyed bijection on [0, 2^30). Exported for tests. */
export function permute(n: number, key: string, bits = INVOICE_CODE_BITS): number {
  const hb = bits / 2;
  const mask = 2 ** hb - 1;
  let l = Math.floor(n / 2 ** hb);
  let r = n % 2 ** hb;
  for (let i = 0; i < ROUNDS; i++) {
    const f = hb === HALF_BITS ? roundFn(key, i, r) : smallRound(key, i, r, mask);
    [l, r] = [r, (l ^ f) & mask];
  }
  return l * 2 ** hb + r;
}

/** Inverse of `permute`. */
export function unpermute(c: number, key: string, bits = INVOICE_CODE_BITS): number {
  const hb = bits / 2;
  const mask = 2 ** hb - 1;
  let l = Math.floor(c / 2 ** hb);
  let r = c % 2 ** hb;
  for (let i = ROUNDS - 1; i >= 0; i--) {
    const f = hb === HALF_BITS ? roundFn(key, i, l) : smallRound(key, i, l, mask);
    [l, r] = [(r ^ f) & mask, l];
  }
  return l * 2 ** hb + r;
}

// Same construction on a tiny domain, so the test suite can prove bijection exhaustively.
function smallRound(key: string, round: number, half: number, mask: number): number {
  const mac = createHmac("sha256", key).update(`inv-code-v1|${round}|${half}`).digest();
  return ((mac[0] << 8) | mac[1]) & mask;
}

export function encodeCode(value: number): string {
  let out = "";
  for (let i = 0; i < INVOICE_CODE_LENGTH; i++) {
    out = ALPHABET[value % 32] + out;
    value = Math.floor(value / 32);
  }
  return out;
}

export function decodeCode(code: string): number | null {
  const c = code.toUpperCase().replace(/O/g, "0").replace(/[IL]/g, "1");
  if (c.length !== INVOICE_CODE_LENGTH) return null;
  let v = 0;
  for (const ch of c) {
    const d = ALPHABET.indexOf(ch);
    if (d < 0) return null;
    v = v * 32 + d;
  }
  return v;
}

let warned = false;
function warnOnce(msg: string) {
  if (warned) return;
  warned = true;
  console.error(`[invoice-number] ${msg}`);
}
/** Test hook. */
export function _resetInvoiceNumberWarning() {
  warned = false;
}

/** The legacy sequential display: prefix + zero-padded internal number. ADMIN/BOOKS ONLY. */
export function legacyInvoiceNumber(number: number, prefix: string): string {
  return `${prefix}${String(number).padStart(5, "0")}`;
}

/**
 * THE one function every customer-facing surface calls: HTML, PDF (+ filename), emails,
 * dashboard lists/detail, exports. Accepts an invoice (anything with `number`) or the bare
 * number, and either an `InvoiceBranding` or a prefix string.
 */
export function displayInvoiceNumber(
  invoice: { number: number } | number,
  branding: { numberPrefix: string } | string,
  cfg: OpaqueConfig = opaqueConfigFromEnv(),
): string {
  const number = typeof invoice === "number" ? invoice : invoice.number;
  const prefix = typeof branding === "string" ? branding : branding.numberPrefix;
  if (cfg.after === null || number <= cfg.after) return legacyInvoiceNumber(number, prefix);
  if (!cfg.key) {
    warnOnce(
      "INVOICE_OPAQUE_AFTER is set but INVOICE_DISPLAY_KEY is missing or shorter than 16 chars — " +
        "falling back to SEQUENTIAL invoice numbers. Set INVOICE_DISPLAY_KEY.",
    );
    return legacyInvoiceNumber(number, prefix);
  }
  if (!Number.isInteger(number) || number < 0 || number >= INVOICE_CODE_DOMAIN) {
    warnOnce(`invoice number ${number} is outside the 2^30 opaque-code domain — using legacy display.`);
    return legacyInvoiceNumber(number, prefix);
  }
  return `${prefix}${encodeCode(permute(number, cfg.key))}`;
}

/**
 * Support lookup: what internal `Invoice.number` does this user-typed string refer to?
 * Accepts the legacy form ("180", "#180", "INV-00180") and the opaque form ("INV-4F7K29",
 * "4f7k29"). Returns candidate numbers (0, 1 or 2 — a 6-char code made only of digits is
 * also a legal bare number, so both readings are returned and the caller queries both).
 * An opaque reading is only accepted for numbers above the cutoff, so a stray string can't
 * resolve to a legacy-era invoice.
 */
export function resolveInvoiceNumberQuery(
  q: string,
  prefix = "INV-",
  cfg: OpaqueConfig = opaqueConfigFromEnv(),
): number[] {
  let s = q.trim();
  if (s.startsWith("#")) s = s.slice(1);
  const p = prefix.toUpperCase();
  if (s.toUpperCase().startsWith(p)) s = s.slice(p.length);
  else if (/^inv-?/i.test(s)) s = s.replace(/^inv-?/i, "");
  const out: number[] = [];
  if (/^\d{1,9}$/.test(s)) out.push(Number(s));
  if (cfg.after !== null && cfg.key && s.length === INVOICE_CODE_LENGTH) {
    const v = decodeCode(s);
    if (v !== null) {
      const n = unpermute(v, cfg.key);
      if (n > cfg.after && !out.includes(n)) out.push(n);
    }
  }
  return out;
}
