 *
 * The compare-and-swap on `expiresAt` is the idempotency guard. A retried sweep, a
 * second worker or a concurrent `renewNow` all read the same snapshot expiry; only
 * the first `updateMany` to match it writes, and every loser rolls back its debit
 * and its invoice with the transaction. Zero rows matched = someone else already
 * renewed this period, which is a success for us, not an error.
 */
async function commitRenewal(opts: {
  server: DueServer;
  charge: RenewalCharge;
  newExpiry: Date;
  /** Destination country the VAT was charged for (Finding 1); recorded on the invoice. */
  taxCountry?: string;
}): Promise<"renewed" | "insufficient" | "already"> {
  const { server, charge, newExpiry, taxCountry } = opts;
  // Captured from the in-tx invoice.create so the renewal invoice can be emailed
  // (with its PDF) only after the CAS-guarded tx commits — a rolled-back / already-
  // renewed sweep leaves this null and emails nothing.
  let renewedInvoice: { id: string; number: number; amountCents: number } | null = null;
  const renewCents = charge.totalCents;
  const {
    netCents,
    taxCents,
    taxRatePercent,
    extraDiskCents,
    extraDiskMonthlyCents,
    backupCents,
    backupMonthlyCents,
    ipCents,
    retentionDiscountCents,
    partnerDiscountCents,
    partnerDiscountPercent,
  } = charge;
  const periodStart = server.expiresAt!;
  // The pre-discount plan+add-on subtotal, so the invoice's base line can show
  // the real list price and the retention discount can get its OWN negative
  // line beneath it — same reasoning as the extra-disk/backup lines: a
  // customer should be able to see exactly what was discounted, not just a
  // smaller total with no explanation. Both discounts (retention, then partner)
  // are added back to reach the true pre-discount subtotal.
  const preRetentionNetCents = netCents + retentionDiscountCents + partnerDiscountCents;

  // `renewalCharge` bills `vpsTermPriceCents` (or a game plan's flat price) with NO
  // seasonal promo — renewals never get the intro discount, exactly as
  // lib/promotions.ts promises. So the months this renewal adds were sold at 0% off
  // and the term's stored rate basis must say so, or a later downgrade credits them
  // at a promo rate nobody was ever charged. Blended rather than overwritten for the
  // same reason as renewNow: this sweep only fires on already-expired servers (so
  // the blend is 0 in practice), but the shared helper means the two renewal paths
  // cannot express different rules for the same event.
  const renewedPercent = prorateBlendPercent({
    currentPercent: resolveTermPromoPercent(server.termPromoPercent),
    currentMonths: remainingMonths(server.expiresAt, Date.now()),
    addedPercent: 0,
    addedMonths: charge.months,
  });

  try {
    await db.$transaction(async (tx) => {
      const advanced = await tx.server.updateMany({
        where: { id: server.id, expiresAt: server.expiresAt },
        data: {
          expiresAt: newExpiry,
          termPromoPercent: renewedPercent,
          // The period is paid, so the collection state that belonged to it dies
          // with it. Leaving a stage behind would hand the NEXT period a
          // half-spent retry budget and the wrong dunning email.
          dunningStage: 0,
          dunningNextAt: null,
          dunningPayUrl: null,
          // The platform-fault grace belonged to the period just paid for.
          billingGraceUntil: null,
          // RETENTION OFFER: this renewal is the "very next" one the discount was
          // promised for — spent or not (retentionDiscountCents is 0 on every
          // server that never had one pending), it is cleared HERE, in the same
          // CAS-guarded write that advances the period, so it can never silently
          // reapply to the period after this one. A losing/replayed pass matches
          // zero rows (the `where: expiresAt: server.expiresAt` guard) and clears
          // nothing, so a retried sweep can't burn the discount without actually
          // renewing.
          pendingRenewalDiscountPercent: null,
        },
      });
      if (advanced.count === 0) throw new AlreadyRenewedError();
      await debitWallet(tx, server.userId, renewCents);
      await tx.walletTransaction.create({
        data: {
          userId: server.userId,
          amountCents: -renewCents,
          description: `Renewal: ${charge.label} (${server.hostname})`,
        },
      });
      // PAID invoice for this renewal period. Inside the CAS-guarded tx, so a
      // retried/concurrent sweep hits AlreadyRenewedError and rolls back —
      // never producing a second invoice for the same period.
      const renewalInvoice = await tx.invoice.create({
        data: invoiceCreateData({
          userId: server.userId,
          description: `Renewal: ${charge.label} (${server.hostname})`,
          status: "PAID",
          // Snapshot the card on file at charge time (null-safe for wallet-only users).
          paidBrand: server.user.cardBrand ?? null,
          paidLast4: server.user.cardLast4 ?? null,
          // VAT recorded separately; the line items below sum to the NET (netCents).
          taxCents,
          taxRatePercent,
          taxCountry: taxCountry ?? null,
          // Creator Partner Program commission math (lib/partner-commission.ts)
          // needs a real typed number for the dedicated-IP portion of this
          // invoice — never inferred from `lineItems` after the fact.
          dedicatedIpCents: ipCents,
          period: { start: periodStart, end: newExpiry },
          // Extra disk gets its OWN line so the customer sees exactly what the
          // permanent storage costs each cycle; the lines sum back to netCents.
          lineItems: [
            {
              description: `${charge.label} — ${server.hostname}`,
              qty: 1,
              unitCents: preRetentionNetCents - extraDiskCents - backupCents - ipCents,
              amountCents: preRetentionNetCents - extraDiskCents - backupCents - ipCents,
            },
            // Dedicated IP gets its own line too (2026-09-26) — previously folded
            // silently into the base line above; now consistent with how the
            // NEW-order invoice (lib/order.ts placeOrder) has always itemised it.
            // Total is unchanged either way.
            ...(ipCents > 0
              ? [
                  {
                    description: `Dedicated IP — ${server.hostname} ($${(ipCents / Math.max(1, charge.months) / 100).toFixed(2)}/mo)`,
                    qty: 1,
                    unitCents: ipCents,
                    amountCents: ipCents,
                  },
                ]
              : []),
            ...(extraDiskCents > 0
              ? [
                  {
                    description: `${extraDiskLabel(server.extraDiskGB)} — ${server.hostname} (permanent, $${(extraDiskMonthlyCents / 100).toFixed(2)}/mo)`,
                    qty: 1,
                    unitCents: extraDiskCents,

