 * never to price an actual charge. A visitor in this state has no PartnerCustomer
 * row yet (that is only created at registration — see lib/actions.ts register()),
 * so there is nothing to look up but the code itself.
 */
export async function partnerPreviewForCode(
  rawCode: string | null | undefined,
): Promise<{ active: boolean; partnerName: string | null }> {
  const code = (rawCode ?? "").trim().toUpperCase();
  if (!code) return { active: false, partnerName: null };
  const partner = await db.referralPartner.findUnique({
    where: { code },
    select: { status: true, name: true },
  });
  if (!partner || partner.status !== "ACTIVE") return { active: false, partnerName: null };
  return { active: true, partnerName: partner.name };
}

/**
