    totalCents: charge.totalCents,
    netCents: charge.netCents,
    taxCents: charge.taxCents,
    taxRatePercent: charge.taxRatePercent,
    retentionDiscountCents: charge.retentionDiscountCents,
    ipCents: charge.ipCents,
    partnerDiscountCents: charge.partnerDiscountCents,
    partnerDiscountPercent: charge.partnerDiscountPercent,
    months: charge.months,
    durationLabel: charge.months === 1 ? "1 month" : `${charge.months} months`,
    label: charge.label,
  };
}
