/**
 * Renewal notice printed on invoices ("Renews at $75.80/month on Nov 6, 2026").
 * PURE — no database — so the HTML, PDF and email renderers can all import it.
 * The snapshot itself is written at invoice creation by lib/invoice-renewal-snapshot.ts.
 */
export type InvoiceRenewalFields = {
  renewalCents?: number | null;
  renewalTermMonths?: number | null;
  renewalDate?: Date | string | null;
};

function usd(cents: number): string {
  return `$${(Math.abs(cents) / 100).toFixed(2)}`;
}

function longDate(d: Date | string): string {
  // UTC so the printed date is the stored date regardless of server timezone.
  return new Date(d).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric", timeZone: "UTC" });
}

/** "month", "year", or "N months" for the cadence phrase. */
function termPhrase(months: number): { per: string } {
  if (months === 1) return { per: "/month" };
  if (months === 12) return { per: "/year" };
  return { per: ` every ${months} months` };
}

