import type { Prisma } from "@prisma/client";
import { db } from "./db";
import { renewalCharge } from "./renewal-charge";
import { currentRenewalPrices } from "./admin-metrics";
import { taxContextForUser } from "./tax";
import { partnerDiscountForRenewal } from "./partner-pricing";

/** Fields stamped on an Invoice (see schema: serverId, renewalCents, renewalTermMonths, renewalDate). */
export type RenewalSnapshot = {
  serverId: string;
  renewalCents: number;
  renewalTermMonths: number;
  renewalDate: Date;
};

type Client = Prisma.TransactionClient | typeof db;

/**
 * Snapshot of what the NEXT renewal of `serverId` will charge, computed by calling the
 * same `renewalCharge` the billing sweep / Renew-now use (grandfathered rate, plan or
 * game-plan price, recurring add-ons, annual discount, the owner's tax rate and partner
 * discount; the one-time retention offer is excluded via `nextCycleTotalCents`).
 *
 * Returns null when there is nothing to promise: server missing, free/zero-priced.
 * `renewalDate` defaults to the server's current `expiresAt` (the date the next charge
 * lands); pass one explicitly when the caller knows better. Pass the transaction client
 * when called inside the charge transaction so it sees rows written in the same tx.
 */
export async function renewalSnapshotForServer(
  serverId: string,
  client: Client = db,
  opts: { renewalDate?: Date | null } = {},
): Promise<RenewalSnapshot | null> {
  const server = await client.server.findUnique({
    where: { id: serverId },
    include: { plan: true, gamePlan: true, dedicatedIp: true, user: { select: { billingCountry: true, vatId: true } } },
  });
  if (!server) return null;
  const date = opts.renewalDate ?? server.expiresAt;
  if (!date) return null;
  const [basePrices, tax, partner] = await Promise.all([
    currentRenewalPrices(),
    taxContextForUser(server.user),
    partnerDiscountForRenewal(server.userId),
  ]);
  const charge = renewalCharge(server, {
    ...basePrices,
    taxRatePercent: tax.ratePercent,
    partnerDiscountPercent: partner.percent,
  });
  if (!(charge.nextCycleTotalCents > 0)) return null;
  return {
    serverId,
    renewalCents: charge.nextCycleTotalCents,
    renewalTermMonths: charge.months,
    renewalDate: date,
  };
}

/** Compute + write the snapshot onto an existing invoice (orders: invoice precedes the server row). */
export async function attachRenewalSnapshot(
  client: Client,
  invoiceId: string,
  serverId: string,
  opts: { renewalDate?: Date | null } = {},
): Promise<void> {
  const snap = await renewalSnapshotForServer(serverId, client, opts);
  // Even when there is no price to promise, record which server the invoice belongs to.
  await client.invoice.update({
    where: { id: invoiceId },
    data: snap ?? { serverId },
  });
}
