}): Promise<void> {
  const { server, newPlan, prorateCents: quoted } = await resizeQuote(opts.serverId, opts.planId);
  const prorateCents = opts.chargeCents ?? quoted;

  const pending = await db.job.count({ where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } } });
  if (pending > 0) throw new ResizeError("Another operation is already in progress on this server.");

  try {
    await db.$transaction(async (tx) => {
      // The PAID invoice's id rides on the job so a terminal failure's refund
      // (worker reconcileFailedJob) can also reverse any partner commission
      // earned on exactly this charge.
      let invoiceId: string | null = null;
      if (prorateCents > 0) {
        await debitWallet(tx, server.userId, prorateCents);
        await tx.walletTransaction.create({
          data: {
            userId: server.userId,
            amountCents: -prorateCents,
            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
          },
        });
        // PAID invoice for the proration charge (one per user-initiated resize).
        const inv = await tx.invoice.create({
          data: invoiceCreateData({
            userId: server.userId,
            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
            status: "PAID",
            lineItems: [
              { description: `Upgrade to ${newPlan.name} — prorated for remaining term (${server.hostname})`, qty: 1, unitCents: prorateCents, amountCents: prorateCents },
            ],
          }),
          select: { id: true },
        });
        invoiceId = inv.id;
      }
      // NOTE: a plan change deliberately does NOT touch `termPromoPercent`. It does
      // not re-base the term — `expiresAt` is untouched and no new months are sold —
      // it only moves the customer to a different plan at the rate they already
      // bought. Keeping the scalar is exactly what makes upgrade-then-downgrade net
      // to zero: both halves read the same stored basis. (This is also why the basis
      // is stored as a percent rather than a $/mo figure: a cents rate would have to
      // be rewritten here, and that rewrite is one more place to get it wrong.)
      //
      // Record the amount charged on the job so the worker's RESIZE handler can
      // REVERSE it (credit `payload.prorateCents` back to the wallet) if the
      // resize terminally fails — money is committed here, before the job runs.
      await tx.job.create({
        data: { type: "RESIZE", serverId: server.id, payload: { planId: opts.planId, prorateCents, direction: "up", invoiceId } as any },
      });
      await tx.auditLog.create({
        data: { userId: opts.actorUserId, action: "server.resize", detail: `${server.id} -> ${newPlan.slug} prorate=${prorateCents}` },
      });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) throw new ResizeError("Insufficient balance — top up your wallet first.");
