async function resolveInvoiceAction(userId: string, idOrNumber: string, label?: string): Promise<AccountActionCard | null> {
  const asNumber = Number.parseInt(idOrNumber.replace(/^#/, ""), 10);
  const invoice = Number.isFinite(asNumber)
    ? await db.invoice.findFirst({ where: { userId, number: asNumber }, select: { id: true, number: true, status: true } })
    : await db.invoice.findFirst({ where: { userId, id: idOrNumber }, select: { id: true, number: true, status: true } });
  if (!invoice) return null;
  return {
    type: "action",
    key: `inv_${invoice.id}`,
    kind: "invoice",
    title: `Invoice #${invoice.number}`,
    subtitle: invoice.status,
    ctaLabel: label?.trim() || ACTION_LABELS.invoice,
    ctaUrl: `/dashboard/invoices/${invoice.id}`,
  };
}

