import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";
import {
  permute, unpermute, encodeCode, decodeCode, displayInvoiceNumber, resolveInvoiceNumberQuery,
  legacyInvoiceNumber, _resetInvoiceNumberWarning, INVOICE_CODE_DOMAIN,
} from "../lib/invoice-number";

const KEY = "unit-test-secret-key-0123456789";
const CFG = { key: KEY, after: 180 };

test("permutation is a bijection: exhaustive over a small domain (16 bits)", () => {
  const seen = new Set<number>();
  for (let n = 0; n < 65536; n++) {
    const c = permute(n, KEY, 16);
    assert.ok(c >= 0 && c < 65536);
    seen.add(c);
    assert.equal(unpermute(c, KEY, 16), n);
  }
  assert.equal(seen.size, 65536);
});

test("full 30-bit permutation: inverse + uniqueness over a sampled range", () => {
  const seen = new Set<number>();
  for (let n = 0; n < 40000; n++) {
    const c = permute(n, KEY);
    assert.ok(c >= 0 && c < INVOICE_CODE_DOMAIN);
    assert.equal(unpermute(c, KEY), n);
    seen.add(c);
  }
  assert.equal(seen.size, 40000);
  for (const n of [INVOICE_CODE_DOMAIN - 1, INVOICE_CODE_DOMAIN - 2, 2 ** 29, 2 ** 15, 2 ** 15 - 1]) {
    assert.equal(unpermute(permute(n, KEY), KEY), n);
  }
});

test("codes round-trip and are 6 unambiguous chars", () => {
  for (const v of [0, 1, 31, 32, 123456789, INVOICE_CODE_DOMAIN - 1]) {
    const s = encodeCode(v);
    assert.match(s, /^[0-9A-HJKMNP-TV-Z]{6}$/);
    assert.equal(decodeCode(s), v);
    assert.equal(decodeCode(s.toLowerCase()), v);
  }
  assert.equal(decodeCode("ABC"), null);
  assert.equal(decodeCode("ABCDEU"), null);
});

test("deterministic, keyed, and does not leak order", () => {
  const a = displayInvoiceNumber(181, "INV-", CFG);
  assert.equal(a, displayInvoiceNumber({ number: 181 }, { numberPrefix: "INV-" }, CFG));
  assert.match(a, /^INV-[0-9A-Z]{6}$/);
  assert.notEqual(a, displayInvoiceNumber(181, "INV-", { key: "another-secret-key-0123456789", after: 180 }));
  // consecutive numbers are not consecutive / monotonic codes
  const codes = Array.from({ length: 200 }, (_, i) => decodeCode(displayInvoiceNumber(181 + i, "", CFG))!);
  let ups = 0;
  for (let i = 1; i < codes.length; i++) if (codes[i] > codes[i - 1]) ups++;
  assert.ok(ups > 60 && ups < 140, `looks ordered: ${ups}/199 increases`);
  assert.ok(!a.includes("00181") && !a.includes("181"));
});

