test("inverse lookup: legacy forms and opaque code both resolve (support search)", () => {
  const shown = displayInvoiceNumber(181, "INV-", CFG);
  assert.deepEqual(resolveInvoiceNumberQuery(shown, "INV-", CFG), [181]);
  assert.deepEqual(resolveInvoiceNumberQuery(shown.toLowerCase(), "INV-", CFG), [181]);
  assert.deepEqual(resolveInvoiceNumberQuery(shown.slice(4), "INV-", CFG), [181]);
  assert.deepEqual(resolveInvoiceNumberQuery("INV-00180", "INV-", CFG), [180]);
  assert.deepEqual(resolveInvoiceNumberQuery("#180", "INV-", CFG), [180]);
  assert.deepEqual(resolveInvoiceNumberQuery("180", "INV-", CFG), [180]);
  // a code that decodes to a legacy-era number is NOT accepted as opaque
  const legacyEra = encodeCode(permute(50, KEY));
  assert.deepEqual(resolveInvoiceNumberQuery(legacyEra, "INV-", CFG).filter((n) => n === 50), []);
  // without the key the opaque form can't be resolved
  assert.deepEqual(resolveInvoiceNumberQuery(shown, "INV-", { key: null, after: 180 }), []);
});

