function walk(dir: string, out: string[] = []): string[] {
  for (const f of readdirSync(dir)) {
    if (f === "node_modules" || f === ".next" || f.startsWith(".")) continue;
    const p = join(dir, f);
    if (statSync(p).isDirectory()) walk(p, out);
    else if (/\.(ts|tsx)$/.test(f)) out.push(p);
  }
  return out;
}
const ROOT = new URL("..", import.meta.url).pathname;
const strip = (s: string) => s.replace(/\/\*[\s\S]*?\*\//g, "").replace(/^\s*\/\/.*$/gm, "");

test("only admin surfaces may call the legacy formatInvoiceNumber( / padStart invoice formats", () => {
  const ALLOWED = new Set([
    "lib/invoices.ts",
    "lib/invoice-number.ts",
    "app/admin/invoices/page.tsx",
    "app/admin/invoices/[id]/page.tsx",
    "app/api/admin/export/route.ts",
    "app/api/admin/search/route.ts",
  ]);
  const offenders: string[] = [];
  for (const dir of ["app", "lib", "worker", "components"]) {
    for (const f of walk(join(ROOT, dir))) {
      const rel = f.slice(ROOT.length);
      const src = strip(readFileSync(f, "utf8"));
      if (/\bformatInvoiceNumber\(/.test(src) && !ALLOWED.has(rel)) offenders.push(`${rel}: formatInvoiceNumber(`);
      if (/i\.number\)\.padStart|invoice\.number\)\.padStart/.test(src)) offenders.push(`${rel}: padStart on invoice number`);
    }
  }
  assert.deepEqual(offenders, []);
});

test("each customer renderer calls displayInvoiceNumber", () => {
