    "lib/actions-hosting.ts", "lib/actions-email-hosting.ts", "lib/kb-tools.ts",
    "app/dashboard/invoices/page.tsx", "app/dashboard/invoices/[id]/page.tsx", "app/dashboard/billing/page.tsx",
    "app/api/admin/export/route.ts", "app/api/admin/search/route.ts",
  ]) {
