import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { renewalCharge, type PricedServer, type RenewalPrices } from "../lib/renewal-charge";
import { computeRenewalSnapshot, renewalNotice } from "../lib/invoice-renewal";
import { renderInvoiceHTML, invoiceCreateData, type InvoiceBranding } from "../lib/invoices";
import { renderInvoicePDF } from "../lib/invoice-pdf";

const prices: RenewalPrices = { ipMonthlyCents: 299, extraDiskPerGbCents: 10, backupPlusCents: 0, annualDiscountPct: 10 };
function srv(over: Partial<PricedServer> = {}): PricedServer {
  return {
    termMonths: 1, extraDiskGB: 0, plan: { name: "Nebula", priceCents: 1000 }, gamePlan: null, dedicatedIp: null,
    wantsDedicatedIp: false, backupTier: "FREE" as never, ...over,
  };
}
const D = new Date("2026-11-06T00:00:00Z");

test("snapshot equals the renewal-charge function: plain monthly", () => {
  const s = srv();
  const snap = computeRenewalSnapshot("s1", s, prices, D)!;
  assert.equal(snap.renewalCents, renewalCharge(s, prices).totalCents);
  assert.equal(snap.renewalTermMonths, 1);
  assert.equal(snap.serverId, "s1");
});

test("grandfathered rate wins over the live plan price (invoice #180 shape: $75.80/mo)", () => {
  const s = srv({ plan: { name: "Big", priceCents: 9999 }, grandfatheredRenewalCents: 7580 });
  const snap = computeRenewalSnapshot("s1", s, prices, D)!;
  assert.equal(snap.renewalCents, 7580);
  assert.equal(snap.renewalCents, renewalCharge(s, prices).totalCents);
  assert.equal(renewalNotice(snap), "Renews at $75.80/month on Nov 6, 2026");
});

test("recurring add-ons are included (extra disk + dedicated IP)", () => {
  const s = srv({ extraDiskGB: 50, dedicatedIp: {}, wantsDedicatedIp: true });
  const snap = computeRenewalSnapshot("s1", s, prices, D)!;
  assert.equal(snap.renewalCents, 1000 + 500 + 299);
  assert.equal(snap.renewalCents, renewalCharge(s, prices).totalCents);
});

test("annual term: price covers the term, notice says /year", () => {
  const s = srv({ termMonths: 12, annualDiscountPct: 10 });
  const snap = computeRenewalSnapshot("s1", s, prices, D)!;
  assert.equal(snap.renewalTermMonths, 12);
  assert.equal(snap.renewalCents, renewalCharge(s, prices).totalCents);
  assert.match(renewalNotice(snap)!, /^Renews at \$\d+\.\d\d\/year on Nov 6, 2026$/);
});

test("owner's tax and partner discount flow through (what the sweep charges)", () => {
  const p = { ...prices, taxRatePercent: 20, partnerDiscountPercent: 10 };
  const s = srv();
  assert.equal(computeRenewalSnapshot("s1", s, p, D)!.renewalCents, renewalCharge(s, p).totalCents);
});

test("one-time retention discount is NOT baked into the promised next renewal", () => {
