  assert.equal(charge.nextCycleTotalCents, 1000);
  assert.equal(computeRenewalSnapshot("s1", s, prices, D)!.renewalCents, 1000);
  assert.equal(renewalCharge(srv(), prices).nextCycleTotalCents, 1000);
});

